# Let's check what depths we can actually reach
def bfs_all_depths(graph, start):
    visited = set([start])
    queue = deque([(start, 0)])
    depth_map = defaultdict(set)
    depth_map[0].add(start)

    while queue:
        node, depth = queue.popleft()
        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited.add(neighbor)
                queue.append((neighbor, depth + 1))
                depth_map[depth + 1].add(neighbor)

    return depth_map

