# Let's trace the path to depth 6 to understand the structure
def find_path_to_node(graph, start, target):
    """Find a path from start to target using BFS"""
    visited = {start: None}
    queue = deque([start])

    while queue:
        node = queue.popleft()
        if node == target:
            # Reconstruct path
            path = []
            while node is not None:
                path.append(node)
                node = visited[node]
            return path[::-1]

        for neighbor in graph.get(node, []):
            if neighbor not in visited:
                visited[neighbor] = node
                queue.append(neighbor)
    return None

